// Throwaway: the two-canvas spike's host. GPUI paints first (its title,
// time control, and the table's handle, over a dark page); the scene's
// module (Three.js) and the elements load after its first frame.
import { boot } from '@seiza/web/bootstrap';
import fontUrl from '@seiza/web/fonts/IBMPlexSans-Regular.ttf?url';
// Generated by wasm-bindgen into pkg/ (gitignored); `run.ts` builds it.
import init, { elements_ptr, fly_done, group_radius, load_elements, load_magnitudes, load_rows, magnitudes_ptr, sort_ms, scene_flight, scene_inset, scene_moves, scene_years, spike_state, start } from '../pkg/kirkwood_spike.js';
import wasmUrl from '../pkg/kirkwood_spike_bg.wasm?url';
import { compositeByAlpha } from './alpha.ts';
import type { BeltScene } from './scene.ts';

type Kirkwood = {
  /** Called by the crate: a wheel over the scene. */
  wheel(x: number, y: number, delta: number): void;
  /** Called by the crate once GPUI's first frame is on screen. */
  firstFrame(): void;
  /** Called by the crate: the scene's camera, to pick a shape's rows. */
  viewProjection(): Float32Array;
  /** Called by the crate: the camera to a drawn group, and back. */
  flyTo(x: number, y: number, z: number, radius: number, inset: number, ms: number): void;
  flyHome(ms: number): void;
  /** Called by the crate: the group's rows (a view over its memory), and
   *  the closed shape. */
  setPicked(picked: Uint8Array): void;
  setOutline(points: Float32Array): void;
  /** For `run.ts`: the group's radius once time has run on. */
  groupRadius(yearsAhead: number): number;
  /** For `run.ts`. */
  scene?: BeltScene;
  state(): number[];
  /** For `run.ts`: the wasm's linear memory (bytes), and what the rows in
   *  memory make of a sort (ms: by diameter, by full_name). */
  wasmBytes(): number;
  sortMs(): number[];
  alpha: boolean;
};

let memory: WebAssembly.Memory | undefined;
let scene: BeltScene | undefined;

/** Whether a part of the look is on (src/look.ts's rule, read here without
 *  its module: Three.js loads after the first frame). */
const query = new URLSearchParams(location.search);
const wants = (part: string) => (query.has(part) ? query.get(part) !== '0' : query.has('look') && query.get('look') !== '0');

async function afterFirstFrame(): Promise<void> {
  const file = async (name: string) => {
    const response = await fetch(name);
    if (!response.ok) throw new Error(`${name}: ${response.status} (run data.ts)`);
    return response.arrayBuffer();
  };
  // The sky arrives on its own: the belt doesn't wait for it.
  const sky = wants('stars') ? file('/stars.bin') : undefined;
  const [{ startScene }, elements, magnitudes] = await Promise.all([import('./scene.ts'), file('/elements.bin'), wants('mag') ? file('/h.bin') : undefined]);
  // `?rows`: the sample's other columns, held in the crate, the table over
  // them. Asked for once the elements are in, so the belt never waits on
  // the table's file or shares the link with it. `?rows=gz` fetches them
  // gzipped (`sizing.ts` writes the file): the preview server sends a .bin
  // as it is and a .gz with `Content-Encoding: gzip`, so the browser
  // inflates it, as it would a visitor's.
  const sample = query.has('rows') ? file(query.get('rows') === 'gz' ? '/rows.bin.gz' : '/rows.bin') : undefined;
  scene = startScene(document.querySelector<HTMLCanvasElement>('#scene')!, { years: scene_years, flight: scene_flight, inset: scene_inset, moves: scene_moves, flown: fly_done });
  kirkwood.scene = scene;
  performance.mark('kirkwood:scene');
  const rows = load_elements(new Uint8Array(elements));
  if (magnitudes) load_magnitudes(new Uint8Array(magnitudes));
  // Views over the crate's own buffers: no copy on this side. Made after
  // both loads returned and uploaded before anything else runs
  // (`setElements` draws), since the memory growing would detach them.
  scene.setElements(new Float32Array(memory!.buffer, elements_ptr(), rows * 6), rows, magnitudes && new Float32Array(memory!.buffer, magnitudes_ptr(), rows));
  performance.mark('kirkwood:belt');
  // The table opens when its rows are held; a failure is the page's error.
  const table = sample?.then((rowsFile) => {
    performance.mark('kirkwood:rows-in');
    if (!load_rows(new Uint8Array(rowsFile))) throw new Error("rows.bin isn't the elements' rows file (run data.ts, then sizing.ts)");
    performance.mark('kirkwood:rows-held');
  });
  if (sky) scene.setStars(await sky);
  performance.mark('kirkwood:sky');
  await table;
}

const kirkwood: Kirkwood = {
  wheel: (x, y, delta) => scene?.wheel(x, y, delta),
  firstFrame: () => void afterFirstFrame(),
  viewProjection: () => scene?.viewProjection() ?? new Float32Array(),
  flyTo: (x, y, z, radius, inset, ms) => scene?.flyTo([x, y, z], radius, inset, ms),
  flyHome: (ms) => scene?.flyHome(ms),
  setPicked: (picked) => scene?.setPicked(picked),
  setOutline: (points) => scene?.setOutline(points),
  groupRadius: group_radius,
  state: () => Array.from(spike_state()),
  wasmBytes: () => memory?.buffer.byteLength ?? 0,
  sortMs: () => Array.from(sort_ms()),
  alpha: compositeByAlpha(),
};
(globalThis as unknown as { __kirkwood: Kirkwood }).__kirkwood = kirkwood;
(globalThis as unknown as { __seizaFrameSample: () => object }).__seizaFrameSample = () => ({ scene: scene?.stats.frames ?? 0 });

void boot({
  init: async () => {
    memory = (await init({ module_or_path: wasmUrl })).memory;
  },
  start,
  fontUrl,
  wasmUrl,
});
